    "sourceId": "nasa",
    "sourceUrl": "https://www.nasa.gov/general/copernicus/",
    "sourceFeed": "https://www.nasa.gov/technology/feed/",
    "category": "科學",
    "topic": "General · High-Tech Computing",
    "publishedAt": "2026-08-21",
